{"sql":"CREATE OR REPLACE FUNCTION employees.generate_monthly_report(report_date DATE) RETURNS INTEGER AS $$
DECLARE
    dept_count INTEGER;
    total_emp INTEGER;
    avg_sal DECIMAL;
    new_report_id INTEGER;
BEGIN
    SELECT COUNT(DISTINCT department_id) INTO dept_count FROM employees.department_employee WHERE to_date = '9999-01-01';
    SELECT COUNT(id) INTO total_emp FROM employees.employee;
    SELECT AVG(amount) INTO avg_sal FROM employees.salary WHERE to_date = '9999-01-01';

    INSERT INTO employees.monthly_reports(report_date, department_count, total_employees, avg_salary, generated_at)
    VALUES (report_date, dept_count, total_emp, avg_sal, now()) RETURNING report_id INTO new_report_id;

    RETURN new_report_id;
END;
$$ LANGUAGE plpgsql;"}

{"sql":"CREATE OR REPLACE FUNCTION employees.check_high_salary() RETURNS TRIGGER AS $$
BEGIN
    IF NEW.amount > 120000 THEN
        INSERT INTO employees.salary_alerts(employee_id, salary_amount, alert_date, status)
        VALUES (NEW.employee_id, NEW.amount, now(), 'new');
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER high_salary_alert
AFTER INSERT ON employees.salary
FOR EACH ROW EXECUTE FUNCTION employees.check_high_salary();"}
